sys_variable_value.value:
(function execute(inputs, outputs) {
    var gr = inputs.swap_record;
    if (!gr) {
        outputs.approver_users = [];
        return;
    }

    var swapType = (gr.getValue('swap_type') || '').toString().trim().toUpperCase();
    var approvers = []; // Array of sys_id strings

    // -------------------------------------------------------------
    // 1. Resolve Donor & Donee Hierarchies
    // -------------------------------------------------------------
    var donorGr = gr.donor.getRefRecord();
    var doneeGr = gr.donee.getRefRecord();

    // Donor Attributes
    var donorDepot   = donorGr.getValue('depot') || '';
    var donorRegion  = donorGr.getValue('region') || '';
    var donorZone    = donorGr.getValue('zone') || '';
    var donorSegment = gr.getValue('donor_segment') || donorGr.getValue('segment') || '';

    // Donee Attributes
    var doneeDepot   = doneeGr.getValue('depot') || '';
    var doneeRegion  = doneeGr.getValue('region') || '';
    var doneeZone    = doneeGr.getValue('zone') || '';
    var doneeSegment = gr.getValue('donee_segment') || doneeGr.getValue('segment') || '';

    // -------------------------------------------------------------
    // 2. Approver Matrix Helper Functions
    // -------------------------------------------------------------
    function addUniqueApprover(userId) {
        if (userId) {
            var uid = userId.toString().trim();
            if (uid && approvers.indexOf(uid) === -1) {
                approvers.push(uid);
            }
        }
    }

    function queryMatrix(roleSearch, segmentVal, zoneVal, regionVal, depotVal) {
        var mxGr = new GlideRecord('x_birl3_clm_approval_matrix');
        mxGr.addQuery('customer_type', 'non_trade');

        if (segmentVal) {
            var sq = mxGr.addQuery('segment', segmentVal);
            sq.addOrCondition('segment', segmentVal.toLowerCase());
        }
        if (zoneVal) {
            mxGr.addQuery('zone', zoneVal);
        }
        if (regionVal) {
            mxGr.addQuery('region', regionVal);
        }
        if (depotVal) {
            mxGr.addQuery('depot', depotVal);
        }

        if (roleSearch) {
            mxGr.addEncodedQuery(roleSearch);
        }

        mxGr.query();
        while (mxGr.next()) {
            addUniqueApprover(mxGr.getValue('approver_user'));
        }
    }

    // Role Query Strings
    var ROLE_TSH_TSM = 'role_nameLIKETSH^ORrole_nameLIKETSM';
    var ROLE_RHM     = 'role_nameLIKERHM^ORrole_nameLIKERH CH';
    var ROLE_ZHM     = 'role_nameLIKEZHM^ORrole_nameLIKEZH^ORrole_nameLIKEZH BPD';
    var ROLE_SEG_HEAD = 'role_nameLIKENSH^ORrole_nameLIKEHead RMC^ORrole_nameLIKEHS BPD';

    // -------------------------------------------------------------
    // 3. Routing Paths Based on Swap Type
    // -------------------------------------------------------------

    // SCENARIO A: Same TSH (Intra-Territory) -> Auto Approved
    if (swapType === 'A') {
        outputs.approver_users = []; // No approvers generated
        return;
    }

    // SCENARIO B: Same RHM, Diff TSH (Intra-Region)
    // Chain: Donor TSH -> Shared RHM
    else if (swapType === 'B') {
        // Step 1: Donor TSH (Consent)
        queryMatrix(ROLE_TSH_TSM, donorSegment, donorZone, donorRegion, donorDepot);
        // Step 2: Shared RHM (Final)
        queryMatrix(ROLE_RHM, donorSegment, donorZone, donorRegion, '');
    }

    // SCENARIO C: Same ZHM, Diff RHM, Diff TSH (Intra-Zone)
    // Chain: Donor TSH -> Donor RHM -> Shared ZHM
    else if (swapType === 'C') {
        // Step 1: Donor TSH (Consent)
        queryMatrix(ROLE_TSH_TSM, donorSegment, donorZone, donorRegion, donorDepot);
        // Step 2: Donor RHM (Consent)
        queryMatrix(ROLE_RHM, donorSegment, donorZone, donorRegion, '');
        // Step 3: Shared ZHM (Final)
        queryMatrix(ROLE_ZHM, donorSegment, donorZone, '', '');
    }

    // SCENARIO D: Same Segment Head, Diff ZHM, Diff RHM, Diff TSH (Inter-Zone)
    // Chain: Donor TSH -> Donor RHM -> Donor ZHM -> Shared Segment Head
    else if (swapType === 'D') {
        // Step 1: Donor TSH (Consent)
        queryMatrix(ROLE_TSH_TSM, donorSegment, donorZone, donorRegion, donorDepot);
        // Step 2: Donor RHM (Consent)
        queryMatrix(ROLE_RHM, donorSegment, donorZone, donorRegion, '');
        // Step 3: Donor ZHM (Consent)
        queryMatrix(ROLE_ZHM, donorSegment, donorZone, '', '');
        // Step 4: Segment Head (Final)
        queryMatrix(ROLE_SEG_HEAD, donorSegment, '', '', '');
    }

    // SCENARIO E: Diff Segment Head, Diff ZHM, Diff RHM, Diff TSH (Cross-Segment)
    // Chain: Donor TSH -> Donor RHM -> Donor ZHM -> Donor Segment Head
    else if (swapType === 'E') {
        // Step 1: Donor TSH (Consent)
        queryMatrix(ROLE_TSH_TSM, donorSegment, donorZone, donorRegion, donorDepot);
        // Step 2: Donor RHM (Consent)
        queryMatrix(ROLE_RHM, donorSegment, donorZone, donorRegion, '');
        // Step 3: Donor ZHM (Consent)
        queryMatrix(ROLE_ZHM, donorSegment, donorZone, '', '');
        // Step 4: Donor Segment Head (Final)
        queryMatrix(ROLE_SEG_HEAD, donorSegment, '', '', '');
    }

    // Return the array for the List.sys_user output
    outputs.approver_users = approvers;

})(inputs, outputs);

